type Api=(url:string,options?:RequestInit,csrf?:string)=>Promise<any>;
type Connection={id:string;name:string};
type Destination={id:string;name:string;type:'local'|'sftp'|'ftp'|'smb';path?:string;host?:string;port?:number;username?:string;share?:string;domain?:string;hostFingerprint?:string;retentionDays:number;passwordConfigured:boolean;storageTotalBytes:number|null;storageFreeBytes:number|null;archivedBytes:number};
