type Schedule={id:string;name:string;connection_id:string;connection_name:string;destination_id:string;destination_name:string;cadence:'daily'|'weekly'|'monthly';day_of_week:number|null;day_of_month:number|null;run_time:string;time_zone:string;lookback_days:number;enabled:number;cursor_at:string;backfill_complete:number;next_run_at:string;run_status:string;last_error:string|null;last_finished_at:string|null;pending_count:number;failed_count:number};
type WorkerSchedule={id:string;name:string;connection_name:string;destination_name:string;enabled:number;run_status:string;cursor_at:string;backfill_complete:number;last_started_at:string|null;last_finished_at:string|null;last_error:string|null;updated_at:string;pending_count:number;failed_count:number};
