  const loadLibrary=useCallback(async(nextPage=page,includeUnplayable=showUnplayable,filters=search,q=query)=>{const params=new URLSearchParams({q,page:String(nextPage),pageSize:'25',showUnplayable:String(includeUnplayable)});for(const [key,value] of Object.entries(filters))if(value)params.set(key,value);const value=await request(`/api/library?${params}`);setItems(value.items);setTotal(value.total);setPage(value.page);setMetadataBackfill(value.metadataBackfill||{pending:0,running:0,failed:0,done:0});},[page,query,request,search,showUnplayable]);
