  useEffect(()=>{if(tab!=='library'||metadataBackfill.pending+metadataBackfill.running===0)return;const timer=window.setInterval(()=>void loadLibrary(page).catch(e=>setError((e as Error).message)),5000);return()=>window.clearInterval(timer);},[tab,metadataBackfill.pending,metadataBackfill.running,page,loadLibrary]);
