   function submitLibrarySearch(){setQuery(queryDraft);setSearch({...searchDraft});void loadLibrary(1,showUnplayable,searchDraft,queryDraft);}
  async function saveDestination(event:FormEvent){event.preventDefault();setBusy(true);setError('');setMessage('');try{const body:any={...destinationDraft};if(body.type==='local'){delete body.host;delete body.port;delete body.username;delete body.password;delete body.share;delete body.domain;delete body.hostFingerprint;}else if(body.type==='sftp'){delete body.share;delete body.domain;}else if(body.type==='ftp'){delete body.share;delete body.domain;delete body.hostFingerprint;}else delete body.hostFingerprint;const url=editDestination?`/api/library/destinations/${editDestination}`:'/api/library/destinations';await request(url,{method:editDestination?'PUT':'POST',body:JSON.stringify(body)},csrf);setDestinationDraft({...EMPTY_DEST,path:defaultPath});setEditDestination('');await loadDestinations();void loadDestinationOptions();setMessage('Destination saved and connectivity verified.');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
