  async function deleteDestination(id:string){if(!window.confirm('Delete this destination? It cannot be removed while in use.'))return;setBusy(true);try{await request(`/api/library/destinations/${id}`,{method:'DELETE'},csrf);await loadDestinations();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
