  if(!libraryPlayback&&!libraryAdmin)return <div className="page-content"><div className="page-header"><div><div className="eyebrow">ARCHIVED RECORDINGS</div><h1>Sound Library</h1><p>Your role does not include access to archived recordings.</p></div></div><div className="notice-banner">Library Playback permission is required.</div></div>;
